291: /// Maps a format version and numerical record type identifier to its FeaturePoint ID.
292: ///
293: /// Returns FeaturePoint domain identifier (1..=14), or 0 for unencrypted auxiliary types.
294: /// FeaturePoint 8 designates plaintext bypass (`KeyStorage` 56, `FlightRecordRecover` 50).
295: #[must_use]
296: pub fn get_feature_point(version: u8, record_type: u8) -> u8 {
297:     if version == 13 {
298:         match record_type {
299:             50 | 56 => 8, // PlainText_8 bypass
300:             42 | 57 => 0, // Unencrypted
301:             5 | 9 | 10 | 20 | 24 | 30 | 54 => 7, // DJIFlyCustom_7
302:             12 | 16 | 19 | 22 | 26 | 27 | 28 | 51 | 52 | 55 => 6, // AfterSales_6
303:             49 => 5, // AirLink_5
304:             21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
305:             31 | 32 | 34 | 35 | 36 | 38 | 39 => 3, // Waypoint_3
306:             17 | 18 => 2, // Vision_2
307:             53 => 9, // FlightHub_9
308:             _ => 1, // Base_1
309:         }
310:     } else {
311:         // Version 14 (Granular domain isolation)
312:         match record_type {
313:             50 | 55 | 56 | 209 | 218 | 226 => 8, // PlainText_8 bypass
314:             42 => 0, // Unencrypted
315:             3 => 10, // Gimbal_10
316:             4 | 11 | 29 | 33 | 62 => 11, // RC_11
317:             25 => 12, // Camera_12
318:             7 | 8 | 22 => 13, // Battery_13
319:             28 | 51 | 52 => 14, // FlySafe_14
