321:             12 | 16 | 19 | 26 | 27 => 6, // AfterSales_6
322:             49 | 57 => 5, // AirLink_5
323:             21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
324:             31 | 32 | 34 | 35 | 36 | 38 | 39 | 60 => 3, // Waypoint_3
325:             17 | 18 | 61 => 2, // Vision_2
