//! Empirical Adversarial Challenge Test Suite for Phase 2 Milestone 1: Record Demuxer.
//!
//! Stress tests the parser and stream iterator against malicious, corrupt, and pathological inputs:
//! - Boundary slice sizes (0, 1, 2, 3 bytes)
//! - Extreme / massive declared payload lengths (up to u16::MAX / 65535) exceeding buffer capacity
//! - Delimiter pathologies: missing, corrupted, consecutive (bursts of 0xFF), alternating
//! - Zero-length payloads across v1–v6 (1-byte length) and v7–v14 (2-byte LE length)
//! - Sub-sized payloads in scrambled versions (seed byte without ciphertext)
//! - Stray trailing bytes (0 to 3 bytes before EOF and before details_offset)
//! - Resilient mode monotonic progress guarantees (cursor strictly advances, O(N) bounded steps, no hangs)
//! - Pathological noise streams (10,000+ bytes of pure delimiters, pure zeros, random noise, deceptive headers)
//! - DetailsOffset boundary invariants (negative, zero, sub-header, massive offsets)

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::crypto::derive_key;
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::header::TxtHeader;
use flightreader_core::txt::record::{
    get_feature_point, RawRecordEnvelope, RecordEnvelopeIterator, RecordPayload, RECORD_DELIMITER,
};
use flightreader_core::txt::version::classify_version;

/// Helper to build a standard synthetic 100-byte header buffer.
fn create_hdr(version: u8, header_len: i16, details_offset: i64) -> Vec<u8> {
    let mut buf = vec![0u8; header_len as usize];
    LittleEndian::write_i64(&mut buf[0..8], details_offset);
    LittleEndian::write_i16(&mut buf[8..10], header_len);
    buf[10] = version;
    buf[11] = 3; // DJIFly
    buf[12] = if version >= 7 { 1 } else { 0 };
    buf
}

#[test]
fn challenge_boundary_slices_0_to_3_bytes() {
    // Width 1 (v1–v6): header is 2 bytes (type + len). Wire size for len=0 is 3 bytes.
    // Width 2 (v7–v14): header is 3 bytes (type + len_le16). Wire size for len=0 is 4 bytes.

    // 1. Length 0
    let empty: [u8; 0] = [];
    assert_eq!(
        RawRecordEnvelope::parse(&empty, 1).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );
    assert_eq!(
        RawRecordEnvelope::parse(&empty, 2).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 2. Length 1: [0x01]
    let one = [0x01];
    assert_eq!(
        RawRecordEnvelope::parse(&one, 1).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );
    assert_eq!(
        RawRecordEnvelope::parse(&one, 2).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 3. Length 2: [0x01, 0x00]
    let two = [0x01, 0x00];
    // For width 1: header is 2 bytes, declared payload len = 0. Total wire size = 2 + 0 + 1 = 3 bytes.
    // Input has only 2 bytes -> TruncatedRecord
    assert_eq!(
        RawRecordEnvelope::parse(&two, 1).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 3,
            available: 2
        }
    );
    // For width 2: header is 3 bytes -> UnexpectedEof
    assert_eq!(
        RawRecordEnvelope::parse(&two, 2).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 4. Length 3:
    // Case A: [0x01, 0x00, 0xFF] -> valid len 0 in width 1!
    let three_valid = [0x01, 0x00, RECORD_DELIMITER];
    let (env, consumed) = RawRecordEnvelope::parse(&three_valid, 1).unwrap();
    assert_eq!(consumed, 3);
    assert_eq!(env.record_type, 1);
    assert_eq!(env.payload, &[]);

    // For width 2: header is 3 bytes -> declared payload len = 0xFF00 = 65280!
    // Total wire size = 3 + 65280 + 1 = 65284. Available: 3 -> TruncatedRecord!
    assert_eq!(
        RawRecordEnvelope::parse(&three_valid, 2).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 65284,
            available: 3
        }
    );

    // Case B: [0x01, 0x00, 0x00] -> missing delimiter in width 1, truncated in width 2
    let three_zeros = [0x01, 0x00, 0x00];
    assert_eq!(
        RawRecordEnvelope::parse(&three_zeros, 1).unwrap_err(),
        FlightReaderError::InvalidRecordDelimiter { found: 0x00 }
    );
    assert_eq!(
        RawRecordEnvelope::parse(&three_zeros, 2).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 4,
            available: 3
        }
    );
}

#[test]
fn challenge_massive_declared_payload_length() {
    // Test that massive declared lengths never cause allocation or panic
    let caps_v1 = classify_version(1).unwrap();
    let caps_v7 = classify_version(7).unwrap();

    // 1. Width 1: declared len = 255 in a 10-byte buffer
    let mut buf_v1 = vec![0x01, 0xFF]; // type 1, len 255
    buf_v1.extend_from_slice(&[0xAA; 8]); // only 8 bytes payload
    assert_eq!(
        RawRecordEnvelope::parse(&buf_v1, 1).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 258,
            available: 10
        }
    );

    let mut iter_v1_strict =
        RecordEnvelopeIterator::from_slice(&buf_v1, caps_v1).with_resync(false);
    assert_eq!(
        iter_v1_strict.next().unwrap().unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 258,
            available: 10
        }
    );
    assert!(iter_v1_strict.next().is_none());

    let mut iter_v1_resilient =
        RecordEnvelopeIterator::from_slice(&buf_v1, caps_v1).with_resync(true);
    // In resilient mode, it scans forward byte-by-byte without finding a valid envelope
    assert!(iter_v1_resilient.next().is_none());
    assert_eq!(iter_v1_resilient.cursor(), buf_v1.len());

    // 2. Width 2: declared len = 0xFFFF (65535) in a 20-byte buffer
    let mut buf_v7 = vec![0x02, 0xFF, 0xFF]; // type 2, len 65535
    buf_v7.extend_from_slice(&[0xBB; 17]); // total 20 bytes
    assert_eq!(
        RawRecordEnvelope::parse(&buf_v7, 2).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 3 + 65535 + 1, // 65539
            available: 20
        }
    );

    let mut iter_v7_resilient =
        RecordEnvelopeIterator::from_slice(&buf_v7, caps_v7).with_resync(true);
    assert!(iter_v7_resilient.next().is_none());
    assert_eq!(iter_v7_resilient.cursor(), buf_v7.len());
}

#[test]
fn challenge_corrupted_missing_and_consecutive_delimiters() {
    let caps = classify_version(7).unwrap();

    // 1. Missing delimiter at EOF: payload fits buffer exactly, but last byte is missing
    // [type 1, len 2, seed 42, cipher 10] -> 5 bytes, missing 0xFF
    let missing_del = [0x01, 0x02, 0x00, 0x2A, 0x10];
    assert_eq!(
        RawRecordEnvelope::parse(&missing_del, 2).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 6,
            available: 5
        }
    );

    // 2. Corrupted delimiter: byte at delimiter pos is 0x7E instead of 0xFF
    let corrupt_del = [0x01, 0x02, 0x00, 0x2A, 0x10, 0x7E];
    assert_eq!(
        RawRecordEnvelope::parse(&corrupt_del, 2).unwrap_err(),
        FlightReaderError::InvalidRecordDelimiter { found: 0x7E }
    );

    // 3. Consecutive delimiters: 100 consecutive 0xFF bytes between valid records
    let mut stream = vec![];
    // Valid Record 1: Type 1, len 2, payload [0x2A, 0x99], delimiter 0xFF
    stream.extend_from_slice(&[0x01, 0x02, 0x00, 0x2A, 0x99, RECORD_DELIMITER]);
    // 100 consecutive 0xFF bytes (burst of delimiters / framing padding)
    stream.extend_from_slice(&[RECORD_DELIMITER; 100]);
    // Valid Record 2: Type 4, len 2, payload [0x55, 0x77], delimiter 0xFF
    stream.extend_from_slice(&[0x04, 0x02, 0x00, 0x55, 0x77, RECORD_DELIMITER]);

    let mut iter = RecordEnvelopeIterator::from_slice(&stream, caps).with_resync(true);
    let r1 = iter.next().unwrap().expect("Record 1");
    assert_eq!(r1.record_type, 1);
    assert_eq!(r1.payload, &[0x2A, 0x99]);

    let r2 = iter.next().unwrap().expect("Record 2");
    assert_eq!(r2.record_type, 4);
    assert_eq!(r2.payload, &[0x55, 0x77]);

    assert!(iter.next().is_none());
    assert_eq!(iter.cursor(), stream.len());
}

#[test]
fn challenge_zero_length_payload_semantics_v1_to_v14() {
    // 1. Test v1–v6: [type, 0x00, 0xFF]
    for v in 1..=6 {
        let wire = [0x01, 0x00, RECORD_DELIMITER];
        let (env, total) = RawRecordEnvelope::parse(&wire, 1).unwrap();
        assert_eq!(total, 3);
        assert_eq!(env.payload, &[]);

        let payload = env.decode_payload(v).unwrap();
        assert_eq!(payload.as_slice(), &[]);
        assert!(payload.is_borrowed());

        let mut out = [0u8; 8];
        let slice = env.decode_into(v, &mut out).unwrap();
        assert_eq!(slice, &[]);
    }

    // 2. Test v7–v12: [type, 0x00, 0x00, 0xFF]
    for v in 7..=12 {
        let wire = [0x01, 0x00, 0x00, RECORD_DELIMITER];
        let (env, total) = RawRecordEnvelope::parse(&wire, 2).unwrap();
        assert_eq!(total, 4);
        assert_eq!(env.payload, &[]);

        let payload = env.decode_payload(v).unwrap();
        assert_eq!(payload.as_slice(), &[]);
        assert!(payload.is_borrowed());

        let mut out = [0u8; 8];
        let slice = env.decode_into(v, &mut out).unwrap();
        assert_eq!(slice, &[]);
    }

    // 3. Test v13–v14: [type, 0x00, 0x00, 0xFF]
    for v in 13..=14 {
        let wire = [56, 0x00, 0x00, RECORD_DELIMITER]; // KeyStorage
        let (env, total) = RawRecordEnvelope::parse(&wire, 2).unwrap();
        assert_eq!(total, 4);
        assert_eq!(env.payload, &[]);

        let payload = env.decode_payload(v).unwrap();
        assert_eq!(payload.as_slice(), &[]);
        assert!(payload.is_borrowed());

        let mut out = [0u8; 8];
        let slice = env.decode_into(v, &mut out).unwrap();
        assert_eq!(slice, &[]);
    }

    // 4. Sub-sized payload in v7–v12: payload_len == 1 (seed only, missing ciphertext)
    for v in 7..=12 {
        let wire = [0x01, 0x01, 0x00, 0x42, RECORD_DELIMITER];
        let (env, total) = RawRecordEnvelope::parse(&wire, 2).unwrap();
        assert_eq!(total, 5);
        assert_eq!(env.payload, &[0x42]);

        assert_eq!(
            env.decode_payload(v).unwrap_err(),
            FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 1
            }
        );

        let mut out = [0u8; 8];
        assert_eq!(
            env.decode_into(v, &mut out).unwrap_err(),
            FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 1
            }
        );
    }
}

#[test]
fn challenge_stray_trailing_bytes_before_eof_and_details_offset() {
    let caps_v1 = classify_version(1).unwrap();
    let caps_v7 = classify_version(7).unwrap();

    // 1. Exactly 0 trailing bytes
    let valid_v1 = [0x01, 0x01, 0xAA, RECORD_DELIMITER];
    let mut iter0 = RecordEnvelopeIterator::from_slice(&valid_v1, caps_v1);
    assert_eq!(iter0.next().unwrap().unwrap().payload, &[0xAA]);
    assert!(iter0.next().is_none());
    assert_eq!(iter0.cursor(), valid_v1.len());

    // 2. Exactly 1 trailing byte (0x55)
    let mut stream1 = valid_v1.to_vec();
    stream1.push(0x55);
    let mut iter1 = RecordEnvelopeIterator::from_slice(&stream1, caps_v1);
    assert_eq!(iter1.next().unwrap().unwrap().payload, &[0xAA]);
    assert!(iter1.next().is_none());
    assert_eq!(iter1.cursor(), stream1.len());

    // 3. Exactly 2 trailing bytes in v7 (where header_size = 3)
    let valid_v7 = [0x01, 0x02, 0x00, 0x2A, 0xBB, RECORD_DELIMITER];
    let mut stream2 = valid_v7.to_vec();
    stream2.extend_from_slice(&[0x11, 0x22]);
    let mut iter2 = RecordEnvelopeIterator::from_slice(&stream2, caps_v7);
    assert_eq!(iter2.next().unwrap().unwrap().payload, &[0x2A, 0xBB]);
    assert!(iter2.next().is_none());
    assert_eq!(iter2.cursor(), stream2.len());

    // 4. Exactly 3 trailing bytes in v7 with non-record garbage
    let mut stream3 = valid_v7.to_vec();
    stream3.extend_from_slice(&[0xAA, 0xBB, 0xCC]);
    let mut iter3 = RecordEnvelopeIterator::from_slice(&stream3, caps_v7);
    assert_eq!(iter3.next().unwrap().unwrap().payload, &[0x2A, 0xBB]);
    assert!(iter3.next().is_none());
    assert_eq!(iter3.cursor(), stream3.len());

    // 5. Stray trailing bytes before details_offset in v1–v11
    let mut file_buf = create_hdr(7, 100, 200);
    // Add valid record at offset 100
    file_buf.extend_from_slice(&[0x01, 0x02, 0x00, 0x2A, 0xCC, RECORD_DELIMITER]); // 6 bytes -> ends at 106
    // Fill 106..200 with garbage padding
    file_buf.resize(200, 0xEE);
    // Details block at 200..250
    file_buf.extend_from_slice(&[0x77; 50]);

    let header = TxtHeader::parse(&file_buf).unwrap();
    let mut hdr_iter = RecordEnvelopeIterator::new(&file_buf, &header).unwrap();
    let rec = hdr_iter.next().unwrap().unwrap();
    assert_eq!(rec.record_type, 1);
    assert_eq!(rec.payload, &[0x2A, 0xCC]);
    // Must stop cleanly at details_offset (200) without reading details block
    assert!(hdr_iter.next().is_none());
    assert_eq!(hdr_iter.cursor(), 200);
}

#[test]
fn challenge_resilient_mode_monotonic_progress_and_no_infinite_loop() {
    let caps = classify_version(7).unwrap();

    // 1. Pathological stream of 10,000 pure delimiter bytes (0xFF)
    let burst_ff = vec![RECORD_DELIMITER; 10_000];
    let mut iter_ff = RecordEnvelopeIterator::from_slice(&burst_ff, caps).with_resync(true);
    let mut steps = 0;
    while let Some(_) = iter_ff.next() {
        steps += 1;
        assert!(steps <= 10_000);
    }
    assert_eq!(iter_ff.cursor(), 10_000);

    // 2. Pathological stream of 10,000 pure zeros (0x00)
    let burst_zero = vec![0x00; 10_000];
    let mut iter_zero = RecordEnvelopeIterator::from_slice(&burst_zero, caps).with_resync(true);
    let mut prev_cursor = 0;
    let mut steps_zero = 0;
    while let Some(_) = iter_zero.next() {
        steps_zero += 1;
        assert!(iter_zero.cursor() > prev_cursor);
        prev_cursor = iter_zero.cursor();
        assert!(steps_zero <= 10_000);
    }
    assert_eq!(iter_zero.cursor(), 10_000);

    // 3. Alternating noise: [0xFF, 0x00, 0xFF, 0x00, ...] for 10,000 bytes
    let mut alternating = Vec::with_capacity(10_000);
    for i in 0..10_000 {
        alternating.push(if i % 2 == 0 { 0xFF } else { 0x00 });
    }
    let mut iter_alt = RecordEnvelopeIterator::from_slice(&alternating, caps).with_resync(true);
    let mut steps_alt = 0;
    let mut prev_cursor_alt = 0;
    while let Some(_) = iter_alt.next() {
        steps_alt += 1;
        assert!(iter_alt.cursor() > prev_cursor_alt);
        prev_cursor_alt = iter_alt.cursor();
        assert!(steps_alt <= 10_000);
    }
    assert_eq!(iter_alt.cursor(), 10_000);

    // 4. Deceptive framing stream: valid-looking headers with corrupt delimiters
    // [0x01, 0x02, 0x00, 0x11, 0x22, 0x00] repeated 1,000 times
    let mut deceptive = Vec::with_capacity(6_000);
    for _ in 0..1_000 {
        deceptive.extend_from_slice(&[0x01, 0x02, 0x00, 0x11, 0x22, 0x00]); // 0x00 != 0xFF
    }
    let mut iter_dec = RecordEnvelopeIterator::from_slice(&deceptive, caps).with_resync(true);
    let mut steps_dec = 0;
    while let Some(_) = iter_dec.next() {
        steps_dec += 1;
        assert!(steps_dec <= 6_000);
    }
    assert_eq!(iter_dec.cursor(), 6_000);
}

#[test]
fn challenge_details_offset_boundaries_and_invariants() {
    // 1. details_offset is 0 (less than header_length 100)
    let hdr0 = create_hdr(1, 100, 0);
    let header0 = TxtHeader::parse(&hdr0).unwrap();
    let mut iter0 = RecordEnvelopeIterator::new(&hdr0, &header0).unwrap();
    assert_eq!(iter0.current_offset(), 0);
    assert_eq!(iter0.end_offset(), 0);
    assert!(iter0.next().is_none());

    // 2. details_offset == header_length (100)
    let hdr100 = create_hdr(1, 100, 100);
    let header100 = TxtHeader::parse(&hdr100).unwrap();
    let mut iter100 = RecordEnvelopeIterator::new(&hdr100, &header100).unwrap();
    assert_eq!(iter100.current_offset(), 100);
    assert_eq!(iter100.end_offset(), 100);
    assert!(iter100.next().is_none());

    // 3. details_offset is sub-header (e.g. 50)
    let hdr50 = create_hdr(1, 100, 50);
    let header50 = TxtHeader::parse(&hdr50).unwrap();
    let mut iter50 = RecordEnvelopeIterator::new(&hdr50, &header50).unwrap();
    assert_eq!(iter50.current_offset(), 50);
    assert_eq!(iter50.end_offset(), 50);
    assert!(iter50.next().is_none());

    // 4. details_offset is massive (exceeding buffer len)
    let mut hdr_massive = create_hdr(1, 100, 999_999);
    hdr_massive.extend_from_slice(&[0x01, 0x02, 0x11, 0x22, RECORD_DELIMITER]); // Record at 100..105
    let header_massive = TxtHeader::parse(&hdr_massive).unwrap();
    let mut iter_massive = RecordEnvelopeIterator::new(&hdr_massive, &header_massive).unwrap();
    assert_eq!(iter_massive.end_offset(), hdr_massive.len());
    let rec = iter_massive.next().unwrap().unwrap();
    assert_eq!(rec.record_type, 1);
    assert_eq!(rec.payload, &[0x11, 0x22]);
    assert!(iter_massive.next().is_none());
}

#[test]
fn challenge_deny_unsafe_code_and_crypto_routing() {
    // Verify feature points for v13 and v14
    for rt in [50u8, 56] {
        assert_eq!(get_feature_point(13, rt), 8);
        assert_eq!(get_feature_point(14, rt), 8);
    }
    assert_eq!(get_feature_point(14, 3), 10); // Gimbal
    assert_eq!(get_feature_point(14, 4), 11); // RC
    assert_eq!(get_feature_point(14, 25), 12); // Camera
    assert_eq!(get_feature_point(14, 7), 13); // Battery
    assert_eq!(get_feature_point(14, 28), 14); // FlySafe
    assert_eq!(get_feature_point(14, 42), 0); // Unencrypted

    // Verify XOR roundtrip bit-exactness on boundary sizes
    let key = derive_key(1, 42);
    let mut ciphertext = vec![42u8]; // seed
    let plaintext = [0xAA; 1000];
    for (i, &b) in plaintext.iter().enumerate() {
        ciphertext.push(b ^ key[i % 8]);
    }
    let env = RawRecordEnvelope::new(1, &ciphertext);
    let decoded = env.descramble_xor().unwrap();
    assert_eq!(decoded, plaintext);
}

